数据库样例create table role(    id          bigint auto_increment        primary key,    role        varchar(10)  null,    role_name   varchar(30)  null,    description varchar(256) null,    constraint role        unique (role));create table users(    id       bigint auto_increment        primary key,    username varchar(100) not null,    password varchar(200) not null,    role     varchar(10)  not null,    nickname varchar(10)  not null);

实体类创建public class Users extends BaseDomain implements Serializable &#123;    private static final long serialVersionUID = 438491303269108393L;    private Long id;    private String username;    private String password;    /** 外键 */    @CrossQueryField(tableName = &quot;role&quot;, keyField = &quot;role&quot;, valueField = &quot;roleName&quot;)    @CrossQueryEntity(keyField = &quot;role&quot;, tableName = &quot;role&quot;, valueField = &quot;roleObj&quot;)    private String role;    private String nickname;    /** 关联查询目标 */    private String roleName;    /** 关联实体类 */    private Role roleObj;‘    ... Getter Setter...&#125;

注解定义/** * &lt;p&gt; *  描述:  跨表查询字段注解 *  AOP 切点 * &lt;/p&gt; */@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.METHOD)public @interface CrossQuery &#123;&#125;/** * 描述：关联查询实体类注解 */@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.FIELD)public @interface CrossQueryEntity &#123;    /**     * key字段名     */    String keyField();    /**     * 表名     */    String tableName();    /**     * value字段名，查询目标     */    String valueField();&#125;/** * 关联查询字段注解 */@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.FIELD)public @interface CrossQueryField &#123;    /**     * Key 字段     */    String keyField();    /**     * key Table 字段     */    String tableKeyField() default &quot;&quot;;    /**     * Value 字段     */    String valueField();    /**     * Value Table 字段     */    String tableValueField() default &quot;&quot;;    /**     * tableName     */    String tableName();&#125;

Mapper 定义以及动态 SQL 构建@Mapperpublic interface CommonDbEnhancedMapper &#123;    /**     * 通用K,V型查询     * @param tableName tableName     * @param keyField keyFieldName     * @param valueField valueFieldValue     * @param list 实体列表     * @return list     * @param &lt;T&gt; Entity     */    @SelectProvider(value = CommonProvider.class, method = &quot;selectListUseKeyValue&quot;)    @MapKey(&quot;_xxy&quot;)    &lt;T&gt; Map&lt;Object, JSONObject&gt; selectListUseKeyValue(List&lt;T&gt; list, String tableName, String keyField, String valueField);    /**     * 通用K,V型查询     * @param tableName tableName     * @param keyField keyFieldName     * @param list 实体列表     * @return list     * @param &lt;T&gt; Entity     */    @SelectProvider(value = CommonProvider.class, method = &quot;selectMap&quot;)    @MapKey(&quot;_xxy&quot;)    &lt;T&gt; Map&lt;Object, JSONObject&gt; selectMap(List&lt;T&gt; list, String tableName, String keyField);&#125;/** * SQL 构建类 */public class CommonProvider &#123;    public static &lt;T&gt; String selectListUseKeyValue(List&lt;T&gt; list, String tableName, String keyField, String valueField) &#123;        StringBuilder sql = new StringBuilder();        // Generate keys        String ids = SqlUtils.getIds(list, keyField);        String tableKey = SqlUtils.camelToUnderline(keyField);        String tableValue = SqlUtils.camelToUnderline(valueField);        sql.append(&quot;SELECT &quot;)                .append(tableKey)                .append(&quot; AS _xxy&quot;)                .append(&quot;,&quot;)                .append(tableValue)                .append(&quot; AS value&quot;)                .append(&quot; FROM &quot;)                .append(tableName)                .append(&quot; WHERE &quot;)                .append(keyField)                .append(&quot; IN (&quot;)                .append(ids)                .append(&quot;)&quot;);        return sql.toString();    &#125;    public static &lt;T&gt; String selectMap(List&lt;T&gt; list, String tableName, String keyField) &#123;        StringBuilder sql = new StringBuilder();        String ids = SqlUtils.getIds(list, keyField);        String tableKey = SqlUtils.camelToUnderline(keyField);        sql.append(&quot;SELECT * ,&quot;)                .append(tableKey)                .append(&quot; AS _xxy&quot;)                .append(&quot; FROM &quot;)                .append(tableName)                .append(&quot; WHERE &quot;)                .append(tableKey)                .append(&quot; IN (&quot;)                .append(ids)                .append(&quot;)&quot;);        return sql.toString();    &#125;&#125;/** * SqlUtils 工具类 */public class SqlUtils &#123;    /**     *     * @param list entity&#x27;s list     * @param fieldName entity field name     * @return &quot;v1,v2,v3&quot;     * @param &lt;T&gt; clazz     */    public static &lt;T&gt; String getIds(List&lt;T&gt; list, String fieldName) &#123;        if (CollectionUtils.isEmpty(list)) &#123;            return null;        &#125;        Class&lt;?&gt; clazz = list.get(0).getClass();        Field field = ReflectUtils.getField(clazz, fieldName);        if (field == null) &#123;            return null;        &#125;        field.setAccessible(true);        boolean isString = field.getType().equals(String.class);        String result =  list.stream().map(item -&gt; ReflectionUtils.getField(field, item))                .filter(Objects::nonNull)                .map(item -&gt; String.format(&quot;&#x27;%s&#x27;&quot;, item))                .distinct()                .collect(Collectors.joining(&quot;,&quot;));        if (!StringUtils.hasLength(result)) &#123;            return null;        &#125;        return result;    &#125;    /**     * 驼峰转下划线     * @param camelCaseStr 驼峰字符串     * @return 下划线字符串     */    public static String camelToUnderline(String camelCaseStr) &#123;        if (camelCaseStr == null || camelCaseStr.isEmpty()) &#123;            return camelCaseStr;        &#125;        StringBuilder sb = new StringBuilder();        for (int i = 0; i &lt; camelCaseStr.length(); i++) &#123;            char c = camelCaseStr.charAt(i);            if (Character.isUpperCase(c)) &#123;                // 如果不是第一个字符，前面加下划线                if (i &gt; 0) &#123;                    sb.append(&#x27;_&#x27;);                &#125;                sb.append(Character.toLowerCase(c));            &#125; else &#123;                sb.append(c);            &#125;        &#125;        return sb.toString();    &#125;&#125;

切面实现@Aspect@Componentpublic class CrossQueryAspect &#123;    private static final Logger logger = LoggerFactory.getLogger(CrossQueryAspect.class);    @Resource    private CommonDbEnhancedMapper commonDbEnhancedMapper;    @AfterReturning(value = &quot;@annotation(crossQuery)&quot;, returning = &quot;value&quot;)    public void doAfterReturning(JoinPoint joinPoint, CrossQuery crossQuery, Object value) &#123;        logger.info(&quot;&lt;=== start execute cross query, method &#123;&#125; ====&gt; &quot;, joinPoint.getSignature().getName());        if (value == null) &#123;            logger.info(&quot;return value is null&quot;);            return;        &#125;        MethodSignature signature = (MethodSignature) joinPoint.getSignature();        logger.info(&quot;Signature Return Type: &#123;&#125;&quot;, signature.getReturnType());        List&lt;Object&gt; list = new ArrayList&lt;&gt;();        if (value instanceof BaseDomain || value.getClass().isArray()) &#123;            list.add(value);        &#125; else if (value instanceof List&lt;?&gt;) &#123;            list.addAll((Collection&lt;?&gt;) value);        &#125;        if (CollectionUtils.isEmpty(list)) &#123;            logger.info(&quot;return value is empty&quot;);            return;        &#125;        Class&lt;?&gt; returnClazz = list.get(0).getClass();        Field[] declaredFields = returnClazz.getDeclaredFields();        for (Field declaredField : declaredFields) &#123;            declaredField.setAccessible(true);            CrossQueryField crossQueryField = declaredField.getDeclaredAnnotation(CrossQueryField.class);            CrossQueryEntity crossQueryEntity = declaredField.getDeclaredAnnotation(CrossQueryEntity.class);            if (crossQueryField != null) &#123;                processCrossQuery(crossQueryField, returnClazz, list);            &#125;            if (crossQueryEntity != null) &#123;                processCrossQuery(crossQueryEntity, returnClazz, list);            &#125;        &#125;    &#125;    private void processCrossQuery(CrossQueryEntity queryEntity, Class&lt;?&gt; returnClazz, List&lt;Object&gt; values) &#123;    String keyFieldName = queryEntity.keyField();        String entityFieldName = queryEntity.valueField();        String tableName = queryEntity.tableName();        Field keyField = ReflectUtils.getField(returnClazz, keyFieldName);        Field entityField = ReflectUtils.getField(returnClazz, entityFieldName);        keyField.setAccessible(true);        entityField.setAccessible(true);        Class&lt;?&gt; entityFieldType = entityField.getType();        Map&lt;Object, JSONObject&gt; map = commonDbEnhancedMapper.selectMap(values, tableName, keyFieldName);        for (Object value : values) &#123;            Object key = ReflectionUtils.getField(keyField, value);            JSONObject jsonObject = map.get(key);            Object targetEntity = JSON.parseObject(jsonObject.toJSONString(), entityFieldType, JSONReader.Feature.SupportSmartMatch);            ReflectionUtils.setField(entityField, value, targetEntity);        &#125;    &#125;    private void processCrossQuery(CrossQueryField queryField, Class&lt;?&gt; clazz, List&lt;Object&gt; values) &#123;        String keyFieldName = queryField.keyField();        String valueFieldName = queryField.valueField();        String tableName = queryField.tableName();        if (StringUtils.hasLength(queryField.tableKeyField()))            keyFieldName = queryField.tableKeyField();        if (StringUtils.hasLength(queryField.tableValueField()))            valueFieldName = queryField.tableValueField();        Field keyField = ReflectUtils.getField(clazz, queryField.keyField());        Field valueField = ReflectUtils.getField(clazz, queryField.valueField());        keyField.setAccessible(true);        valueField.setAccessible(true);        Map&lt;Object, JSONObject&gt; map = commonDbEnhancedMapper.selectListUseKeyValue(values, tableName, keyFieldName, valueFieldName);        for (Object object: values) &#123;            Object key = ReflectionUtils.getField(keyField, object);            JSONObject jsonObject = map.get(key);            if (jsonObject != null) &#123;                ReflectionUtils.setField(valueField, object, jsonObject.get(&quot;value&quot;));            &#125;        &#125;    &#125;    private boolean isBaseType(Object value) &#123;        return value.getClass().getClassLoader() == null;    &#125;&#125;

测试使用@CrossQuery建议将 @CrossQuery 放在 Mybatis 的 Mapper 接口方法上，这样在查询完主数据之后，即会进行关联查询，方便后续的业务逻辑处理。
@Mapperpublic interface UsersDao &#123;    /**     * 通过ID查询单条数据     *     * @param id 主键     * @return 实例对象     */    @CrossQuery    Users queryById(Long id);    /**     * 查询指定行数据     * @param users 实例对象     * @return List&lt;Users&gt;     */    @Select(&quot;select * from users&quot;)    @CrossQuery    List&lt;Users&gt; queryAll(Users users);&#125;  // Controller  @GetMapping  public ResponseEntity&lt;List&lt;Users&gt;&gt; queryAll() &#123;      return ResponseEntity.ok(usersDao.queryAll(null));  &#125;  @GetMapping(&quot;&#123;id&#125;&quot;)  public ResponseEntity&lt;Users&gt; queryById(@PathVariable(&quot;id&quot;) Long id) &#123;      return ResponseEntity.ok(this.usersDao.queryById(id));  &#125;

总结这篇文章提出了一种使用 AOP（面向切面编程）和 MyBatis 动态 SQL 功能来处理业务应用中跨表查询的解决方案。主要目的是减少处理实体关联时的代码复杂性和重复性。
核心组件
@CrossQuery 注解：标记需要跨表数据增强的方法
@CrossQueryField 注解：定义字段级别的跨查询关系
@CrossQueryEntity 注解：定义实体级别的跨查询关系
AOP 切面：拦截带有 @CrossQuery 注解的方法并执行数据增强
动态 SQL 提供者：使用 MyBatis 的 @SelectProvider 在运行时构建灵活的查询
基于反射的处理：自动将相关数据映射到目标实体

Mybatis 的拦截器(Plugins)是一个非常有用的一个特性，可以在 Mybatis 操作数据库的生命周期中添加自定义的一些逻辑，非常适合用于做一些数据操作的记录、数据脱敏等功能
Mybatis 的生命周期Mybatis 中 Executor、ParameterHandler、StatementHandler、ResultSetHandler 是 SQL 执行生命周期的四个关键节点，分别对应 Mybatis 中的四个接口。
拦截器Interceptor 是 Mybatis 提供的一个拦截器接口，定义了三个方法，通过 intercept 方法对 Mybatis 生命周期中的节点进行拦截，并返回结果。
public interface Interceptor &#123;    Object intercept(Invocation invocation) throws Throwable;    default Object plugin(Object target) &#123;        return Plugin.wrap(target, this);    &#125;    default void setProperties(Properties properties) &#123;    &#125;&#125;

拦截器注解上述接口需要结合@Intercepts，@Signature 两个注解来完成对方法的拦截
@Documented@Retention(RetentionPolicy.RUNTIME)@Target(&#123;ElementType.TYPE&#125;)public @interface Intercepts &#123;    Signature[] value();&#125;

@Documented@Retention(RetentionPolicy.RUNTIME)@Target(&#123;&#125;)public @interface Signature &#123;    Class&lt;?&gt; type();    String method();    Class&lt;?&gt;[] args();&#125;

@Signature 注解用于指定拦截的方法，包括拦截的类、方法、参数。
三个参数就是 Executor、ParameterHandler、StatementHandler、ResultSetHandler 接口中对应类型、方法名以及参数类型
type: 拦截的类method: 拦截的方法args: 拦截的参数类型
示例：
/** * StatementHandler接口源代码 */public interface StatementHandler &#123;    Statement prepare(Connection connection, Integer transactionTimeout) throws SQLException;    void parameterize(Statement statement) throws SQLException;    void batch(Statement statement) throws SQLException;    int update(Statement statement) throws SQLException;    &lt;E&gt; List&lt;E&gt; query(Statement statement, ResultHandler resultHandler) throws SQLException;    &lt;E&gt; Cursor&lt;E&gt; queryCursor(Statement statement) throws SQLException;    BoundSql getBoundSql();    ParameterHandler getParameterHandler();&#125;/** * 以拦截prepare、getBoundSql方法为例 */@Intercepts(&#123;        @Signature(                type = StatementHandler.class,                method = &quot;prepare&quot;,                args = &#123;java.sql.Connection.class, java.lang.Integer.class&#125;        ),        @Signature(                type = StatementHandler.class,                method = &quot;getBoundSql&quot;,                args = &#123;&#125;        )&#125;)

拦截器方法public interface Interceptor &#123;    Object intercept(Invocation invocation) throws Throwable;    default Object plugin(Object target) &#123;        return Plugin.wrap(target, this);    &#125;    default void setProperties(Properties properties) &#123;    &#125;&#125;

interceptintercept 是拦截器的核心方法，proceed 方法会调用被拦截的方法，返回结果会作为 intercept 方法的返回值。
Invocation 参数内部三个参数，target: 被拦截的对象, method: 被拦截的方法, args: 方法的参数
一个核心的方法 proceed() 调用被拦截的方法
pluginplugin 方法用于为目标对象创建代理对象，决定是否需要对目标对象进行拦截处理。
setPropertiessetProperties 方法用于接收配置文件中设置的属性参数，实现拦截器的可配置化。
